<script setup lang="ts">
// "What this config does": a plain-English description of each program in
// the text, with settings worth a look. Generated by rules from the file,
// no AI. It follows the text it is given (the editor's, debounced).
import { ref, watch } from 'vue'
import type { Program } from '../../bindings/github.com/touhidurabir/visor/internal/describe'
import { ConfigService } from '../../bindings/github.com/touhidurabir/visor/internal/app'
import { describeError } from '../lib/faults'

const props = defineProps<{ content: string | null }>()

const programs = ref<Program[] | null>(null)
const problem = ref<string | null>(null)
let seq = 0

watch(
  () => props.content,
  async (content) => {
    if (content === null) return
    const mine = ++seq
    try {
      const out = await ConfigService.Describe(content)
      if (mine !== seq) return
      programs.value = out ?? []
      problem.value = null
    } catch (e) {
      if (mine !== seq) return
      programs.value = null
      problem.value = describeError(e)
    }
  },
  { immediate: true },
)
</script>

<template>
  <section class="card" aria-labelledby="describe-title">
    <div class="card-head">
      <strong id="describe-title">What this config does</strong>
      <span class="muted small">Generated from the file, no AI</span>
    </div>
    <p v-if="problem" class="muted">Visor can’t describe this file until it parses. {{ problem }}</p>
    <p v-else-if="!programs" class="muted">Loading…</p>
    <p v-else-if="!programs.length" class="muted">This file has no [program:x] section yet.</p>
    <template v-else>
      <div v-for="p in programs" :key="p.Name" class="prog">
        <div class="name mono">{{ p.Name }}</div>
        <p class="text">{{ p.Text }}</p>
        <ul v-if="p.Flags?.length" class="flags">
          <li v-for="f in p.Flags" :key="f" class="flag"><span aria-hidden="true">⚠</span><span class="sr">Worth a look: </span>{{ f }}</li>
        </ul>
      </div>
    </template>
  </section>
</template>

<style scoped>
.card { border: 1px solid var(--line); border-radius: 10px; padding: 16px; display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.card-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px; }
.muted { margin: 0; color: var(--text-muted); }
.small { font-size: 12px; }
.mono { font-family: var(--font-mono); font-size: 12px; }
.prog { display: flex; flex-direction: column; gap: 6px; padding-top: 10px; border-top: 1px solid var(--stopped-bg); }
.name { font-weight: 600; }
.text { margin: 0; line-height: 1.45; user-select: text; }
.flags { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.flag { display: flex; gap: 8px; padding: 8px 10px; border-radius: var(--radius-sm); background: var(--warning-bg); color: var(--warning-fg); user-select: text; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
</style>
